args.sparql:
SELECT ?director ?directorLabel WHERE {
  dbr:Mission:_Impossible_2 dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
} LIMIT 10

SELECT ?prop ?value ?valueLabel WHERE {
  VALUES ?prop { dbo:nationality dbp:nationality }
  dbr:John_Woo ?prop ?value .
  OPTIONAL { ?value rdfs:label ?valueLabel FILTER(lang(?valueLabel) = "en") }
}

SELECT ?director ?directorLabel ?nat WHERE {
  dbr:Mission:_Impossible_2 dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en") }
  OPTIONAL { ?director dbp:nationality ?nat }
} LIMIT 10

SELECT ?director ?directorLabel ?nat WHERE {
  dbr:Mission:_Impossible_2 dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en") }
  OPTIONAL { ?director dbp:nationality ?nat }
} LIMIT 10

output.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?director ?directorLabel ?nat WHERE {
  dbr:Mission:_Impossible_2 dbo:director ?director .
  OPTIONAL {
    ?director rdfs:label ?directorLabel
    FILTER(lang(?directorLabel) = "en")
  }
  OPTIONAL {
    ?director dbp:nationality ?nat
  }
}
LIMIT 10

